const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

const RESULTS_COLLECTION = "results";
const resultsCol = collection(db, RESULTS_COLLECTION);

/**
 * Add a quiz result to Firestore
 * @param {Object} result - { userId?, name?, score, answers?, meta? }
 * @returns {Promise<DocumentReference>} the Firestore DocumentReference
 */
export async function addResult(result = {}) {
  const payload = {
    ...result,
    createdAt: serverTimestamp(),
  };
  return await addDoc(resultsCol, payload);
}

/**
 * Subscribe to results collection snapshot (real-time)
 * Passes the actual QuerySnapshot to your callback (so your App can call snap.docs)
 * @param {(snapshot: QuerySnapshot) => void} cb
 * @param {(error: any) => void} onError
 * @returns {Function} unsubscribe
 */
export function onResultsSnapshot(cb, onError) {
  // Order by createdAt descending for recent-first display.
  // If createdAt is missing on some documents, Firestore will still return them (they sort last).
  const q = query(resultsCol, orderBy("createdAt", "desc"));
  const unsub = onSnapshot(
    q,
    (snapshot) => {
      // Pass the raw QuerySnapshot so caller can map docs, access metadata, etc.
      if (typeof cb === "function") cb(snapshot);
    },
    (err) => {
      console.error("onResultsSnapshot error:", err);
      if (typeof onError === "function") onError(err);
    }
  );
  return unsub;
}

/**
 * Get all results once (no realtime)
 * Returns an array of { id, ...data }
 */
export async function getAllResultsOnce() {
  const snap = await getDocs(resultsCol);
  const arr = [];
  snap.forEach((d) => {
    arr.push({ id: d.id, ...d.data() });
  });
  return arr;
}

/**
 * Export all results as CSV and trigger browser download
 * @param {string|null} filename
 */
export async function exportResultsCsv(filename = null) {
  const rows = await getAllResultsOnce();
  if (!filename) filename = `results-export-${new Date().toISOString().slice(0, 10)}.csv`;

  const header = ["id", "createdAt", "userId", "name", "score", "meta"];
  const escape = (v) => {
    if (v === undefined || v === null) return "";
    const s = typeof v === "object" ? JSON.stringify(v) : String(v);
    return `"${s.replace(/"/g, '""')}"`;
  };

  const lines = [header.join(",")];
  rows.forEach((r) => {
    const created = r.createdAt && typeof r.createdAt.toDate === "function" ? r.createdAt.toDate().toISOString() : "";
    lines.push([
      escape(r.id),
      escape(created),
      escape(r.userId || ""),
      escape(r.name || ""),
      escape(r.score ?? ""),
      escape(r.meta || ""),
    ].join(","));
  });

  const blob = new Blob([lines.join("\n")], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

/**
 * Clear all documents in the results collection.
 * Uses batched deletes (via writeBatch) to avoid too many parallel deletes and to be safe.
 * Note: client-side deletion still depends on your security rules allowing deletions.
 */
export async function clearAllResults() {
  // We'll delete in batches of up to 400 documents at a time.
  const BATCH_SIZE = 400;

  async function deleteBatch() {
    const q = query(resultsCol, limit(BATCH_SIZE));
    const snap = await getDocs(q);
    if (snap.empty) return 0;

    const batch = writeBatch(db);
    snap.forEach((d) => {
      batch.delete(doc(db, RESULTS_COLLECTION, d.id));
    });
    await batch.commit();
    return snap.size;
  }

  // keep deleting until no docs remain
  let totalDeleted = 0;
  // loop - sequential to avoid overloading
  // limit iterations to avoid infinite loops in case of anomalies
  for (let i = 0; i < 100; i++) {
    const deleted = await deleteBatch();
    totalDeleted += deleted;
    if (deleted < BATCH_SIZE) break;
  }

  return { deleted: totalDeleted };
}

/* Export db in case other modules want it */
export { db };
