/* --- certificate generation --- */
async function generateCertificatePNG(participant) {
  try {
    const name = (participant && participant.name) || "Participant Name";
    const designation = (participant && participant.designation) || "";
    const office = (participant && participant.office) || "";
    const dateStr = new Date().toLocaleDateString("en-GB", { timeZone: "Asia/Kolkata" });

    const bg = await new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error("Failed loading certificate background"));
      img.src = certBg;
    });

    const width = bg.naturalWidth || bg.width;
    const height = bg.naturalHeight || bg.height;

    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(bg, 0, 0, width, height);

    const cx = width / 2;
    const nameY = Math.round(height * 0.49);
    const desigOfficeY = Math.round(height * 0.54);
    const dateY = Math.round(height * 0.88);

    const nameFontPx = Math.round(width * 0.035);
    const secondaryFontPx = Math.round(width * 0.025);
    const smallFontPx = Math.round(width * 0.0165);

    function drawText(text, x, y, sizePx, bold=false) {
      ctx.font = `${bold ? "bold " : ""}${sizePx}px "Times New Roman", serif`;
      ctx.fillStyle = "#0b1220";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(text, x, y);
    }

    drawText(name, cx, nameY, nameFontPx, true);
    if (designation || office) {
      const desigOfficeLine = [designation, office].filter(Boolean).join(" – ");
      drawText(desigOfficeLine, cx, desigOfficeY, secondaryFontPx);
    }

    ctx.font = `${smallFontPx}px Arial, sans-serif`;
    ctx.fillStyle = "#111827";
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    ctx.fillText("Date: " + dateStr, width - Math.round(width * 0.06), dateY);

    canvas.toBlob((blob) => {
      if (!blob) {
        const dataUrl = canvas.toDataURL("image/png");
        const a = document.createElement("a");
        a.href = dataUrl;
        a.download = `certificate-${name.replace(/\s+/g, "_")}-${new Date().toISOString().slice(0,10)}.png`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        return;
      }
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `certificate-${name.replace(/\s+/g, "_")}-${new Date().toISOString().slice(0,10)}.png`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 2000);
    }, "image/png");
  } catch (err) {
    console.error("generateCertificatePNG error:", err);
    alert("Failed to create certificate. See console for details.");
  }
}

/* --- Leaderboard --- */
function Leaderboard({ results }) {
  const safeResults = Array.isArray(results) ? results : [];
  const sorted = safeResults.slice().sort((a, b) => (b.score || 0) - (a.score || 0));
  const total = sorted.length;
  return (
    <div style={{ marginTop: 24, background: "#fff", padding: 16, borderRadius: 8, border: "1px solid #e5e7eb" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
        <h2 style={{ margin: 0 }}>Leaderboard</h2>
        <div style={{ color: "red", fontSize: 14, fontWeight: "bold" }}>Total participants: {total}</div>
      </div>

      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr style={{ background: "#f3f4f6" }}>
            <th style={{ padding: 8, border: "1px solid #e6edf3" }}>S.No</th>
            <th style={{ padding: 8, border: "1px solid #e6edf3" }}>Full Name</th>
            <th style={{ padding: 8, border: "1px solid #e6edf3" }}>Designation</th>
            <th style={{ padding: 8, border: "1px solid #e6edf3" }}>Office</th>
            <th style={{ padding: 8, border: "1px solid #e6edf3" }}>Unit</th>
            <th style={{ padding: 8, border: "1px solid #e6edf3" }}>Score</th>
          </tr>
        </thead>
        <tbody>
          {sorted.length === 0 ? (
            <tr><td colSpan="6" style={{ textAlign: "center", padding: 16 }}>No results yet</td></tr>
          ) : (
            sorted.map((r, i) => (
              <tr key={r.id || i}>
                <td style={{ padding: 8, border: "1px solid #eef2f7" }}>{i + 1}</td>
                <td style={{ padding: 8, border: "1px solid #eef2f7" }}>{r.name}</td>
                <td style={{ padding: 8, border: "1px solid #eef2f7" }}>{r.designation}</td>
                <td style={{ padding: 8, border: "1px solid #eef2f7" }}>{r.office}</td>
                <td style={{ padding: 8, border: "1px solid #eef2f7" }}>{r.unit}</td>
                <td style={{ padding: 8, border: "1px solid #eef2f7" }}>{r.score}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

/* --- AdminPanel --- */
function AdminPanel({ questions, results, onLogout, allowRetake }) {
  const safeQuestions = Array.isArray(questions) ? questions : [];
  const safeResults = Array.isArray(results) ? results : [];

  // Chart refs
  const chartCanvasRef = useRef(null);
  const chartInstanceRef = useRef(null);
  const chartWrapperRef = useRef(null);

  // compute unit-wise counts
  const unitCounts = safeResults.reduce((acc, r) => {
    const unit = r.unit || "Unknown";
    acc[unit] = (acc[unit] || 0) + 1;
    return acc;
  }, {});

  const labels = Object.keys(unitCounts).sort();
  const dataCounts = labels.map(l => unitCounts[l]);

  // create/update chart whenever data changes
  useEffect(() => {
    const ctx = chartCanvasRef.current && chartCanvasRef.current.getContext("2d");
    if (!ctx) return;

    if (chartInstanceRef.current) {
      chartInstanceRef.current.data.labels = labels;
      chartInstanceRef.current.data.datasets[0].data = dataCounts;
      chartInstanceRef.current.update();
      return;
    }

    chartInstanceRef.current = new Chart(ctx, {
      type: "bar",
      data: {
        labels,
        datasets: [{
          label: "Participants",
          data: dataCounts,
          backgroundColor: labels.map(() => "rgba(54,162,235,0.6)"),
          borderColor: labels.map(() => "rgba(54,162,235,1)"),
          borderWidth: 1,
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          title: { display: true, text: "Participants per Unit" },
          datalabels: {
            anchor: "end",
            align: "start",
            color: "#111",
            font: {
              weight: "bold",
              size: 13
            },
            formatter: (value) => value
          }
        },
        scales: {
          x: { ticks: { maxRotation: 45, minRotation: 0 } },
          y: { beginAtZero: true, precision: 0 }
        }
      },
      plugins: [ChartDataLabels]
    });

    return () => {
      if (chartInstanceRef.current) {
        try { chartInstanceRef.current.destroy(); } catch (e) {}
        chartInstanceRef.current = null;
      }
    };
  }, [labels.join("|"), dataCounts.join(",")]);

  const clearLeaderboard = async () => {
    if (!window.confirm("Clear all leaderboard results? This cannot be undone.")) return;
    try {
      await clearAllResults();
      alert("Leaderboard cleared.");
    } catch (err) {
      console.error(err);
      alert("Failed to clear leaderboard");
    }
  };

  const exportCSVLocal = () => {
    if (!safeResults || safeResults.length === 0) {
      alert("No results to export");
      return;
    }
    const header = ["Full Name", "Designation", "Office", "Unit", "Score"];
    const rows = safeResults.slice().sort((a,b)=> (b.score||0)-(a.score||0)).map(r => [r.name||"", r.designation||"", r.office||"", r.unit||"", r.score||0]);
    const csvContent = [header, ...rows].map(row => row.map(cell => `\"${String(cell).replace(/\"/g,'\"\"')}\"`).join(",")).join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `quiz-leaderboard-${new Date().toISOString().slice(0,10)}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  // download chart as PNG using html2canvas on wrapper (includes title)
  const downloadChartPNG = async () => {
    if (!chartWrapperRef.current) {
      alert("Chart not ready");
      return;
    }
    try {
      const canvas = await html2canvas(chartWrapperRef.current, { backgroundColor: '#ffffff', scale: 2 });
      const dataUrl = canvas.toDataURL('image/png');
      const a = document.createElement('a');
      a.href = dataUrl;
      a.download = `unit-wise-participants-${new Date().toISOString().slice(0,10)}.png`;
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (err) {
      console.error('downloadChartPNG failed', err);
      alert('Failed to generate chart image. See console for details.');
    }
  };

  return (
    <div style={{ maxWidth: 900, margin: "40px auto", padding: 24 }}>
      <div style={{ background: "#fff", padding: 16, borderRadius: 8, border: "1px solid #e5e7eb" }}>
        <h2>Admin Panel (Read-only Questions)</h2>

        <div style={{ marginTop: 12 }}>
          <h3>Questions (read-only)</h3>
          {safeQuestions.length === 0 ? (<p>No questions available.</p>) : (
            <ul style={{ paddingLeft: 0 }}>
              {safeQuestions.map((q, idx)=>(
                <li key={q.id || idx} style={{ listStyle: "none", marginBottom: 12, border: "1px solid #eef2f7", padding: 12, borderRadius: 8 }}>
                  <div style={{ fontWeight: 700 }}>{q.question}</div>
                  <div style={{ marginTop: 6, color: "#6b7280" }}>Options: {Array.isArray(q.options) ? q.options.join(" | ") : String(q.options)}</div>
                  <div style={{ color: "#6b7280" }}>Answer: {q.answer}</div>
                  <div style={{ color: "#6b7280" }}>Time limit: {q.timeLimit ?? 15}s</div>
                </li>
              ))}
            </ul>
          )}
        </div>

        <div style={{ marginTop: 12, display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button onClick={exportCSVLocal} style={{ padding: "8px 12px", background: "#10b981", color: "#fff", borderRadius: 6, border: "none" }}>Export Leaderboard (CSV)</button>
          <button onClick={clearLeaderboard} style={{ padding: "8px 12px", background: "#dc2626", color: "#fff", borderRadius: 6, border: "none" }}>Clear Leaderboard</button>
          <button onClick={allowRetake} style={{ padding: "8px 12px", background: "#f59e0b", color: "#fff", border: 6, borderRadius: 6 }}>Allow Retake</button>
          <button onClick={downloadChartPNG} style={{ padding: "8px 12px", background: "#2563eb", color: "#fff", borderRadius: 6, border: "none" }}>Download Unit-wise Chart (PNG)</button>
        </div>

        <div style={{ marginTop: 18 }} ref={chartWrapperRef}>
          <div style={{ height: 360, padding: 12, background: '#fff', borderRadius: 8, boxShadow: '0 1px 3px rgba(0,0,0,0.06)' }}>
            <canvas ref={chartCanvasRef} style={{ width: '100%', height: '100%' }} />
          </div>
        </div>

        <Leaderboard results={safeResults} />

        <button onClick={onLogout} style={{ marginTop: 12, padding: "8px 12px", background: "#6b7280", color: "#fff", borderRadius: 6, border: "none" }}>Logout</button>
      </div>
    </div>
  );
}

